javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    var task_short_description = api.data.look_up_a_single_record.result.check.displayValue;
    var task_details = api.state.findingDetails +
        "<br/><br/><b>Resolution Details</b><br/>" +
        api.state.resolutionDetails;

    var task_priority = api.data.look_up_a_single_record.result.check._reference.priority.value;
    console.log(task_priority);
    var source_record = api.data.look_up_a_single_record.result._row_data.uniqueValue;
    var createTaskUrl = "/now/security-center-hub/security-task-record/sn_vsc_security_task/-1/params/from/access_finding?" +
        "task_type=access_finding" +
        "&task_short_description=" + encodeURIComponent(task_short_description) +
        "&source_record=" + source_record +
        "&task_priority=" + task_priority +
        "&task_details=" + encodeURIComponent(task_details);

    return {
        route: null,
        fields: null,
        params: null,
        redirect: null,
        passiveNavigation: null,
        title: null,
        multiInstField: null,
        targetRoute: null,
        external: {
            url: createTaskUrl
        },
        navigationOptions: null
    };
})

